<?php require __DIR__.'/includes/bootstrap.php';if(!cart_items())go('cart.php');$ids=array_keys(cart_items());$in=implode(',',array_fill(0,count($ids),'?'));$s=db()->prepare("SELECT id,name,price,stock FROM products WHERE id IN ($in) AND is_active=1");$s->execute($ids);$items=$s->fetchAll();$total=0;foreach($items as $p)$total+=(float)$p['price']*min((int)$p['stock'],(int)cart_items()[$p['id']]);$error='';if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();$name=trim($_POST['name']??'');$phone=trim($_POST['phone']??'');$city=trim($_POST['city']??'');$address=trim($_POST['address']??'');$notes=trim($_POST['notes']??'');if(!$name||!$phone||!$city||!$address)$error='يرجى تعبئة جميع الحقول المطلوبة.';else{try{$pdo=db();$pdo->beginTransaction();$subtotal=0;$lines=[];foreach(cart_items() as $pid=>$qty){$q=$pdo->prepare('SELECT id,name,price,stock FROM products WHERE id=? AND is_active=1 FOR UPDATE');$q->execute([(int)$pid]);$p=$q->fetch();if(!$p||(int)$p['stock']<(int)$qty)throw new RuntimeException('الكمية المطلوبة غير متوفرة: '.($p['name']??''));$line=(float)$p['price']*(int)$qty;$subtotal+=$line;$lines[]=[$p,(int)$qty,$line];}$number='VF'.date('ymd').strtoupper(bin2hex(random_bytes(3)));$q=$pdo->prepare("INSERT INTO orders(order_number,customer_name,phone,city,address,notes,subtotal,shipping,total) VALUES(?,?,?,?,?,?,?,?,?)");$q->execute([$number,$name,$phone,$city,$address,$notes,$subtotal,0,$subtotal]);$oid=(int)$pdo->lastInsertId();$item=$pdo->prepare('INSERT INTO order_items(order_id,product_id,product_name,unit_price,quantity,line_total) VALUES(?,?,?,?,?,?)');$stock=$pdo->prepare('UPDATE products SET stock=stock-? WHERE id=?');foreach($lines as [$p,$qty,$line]){$item->execute([$oid,$p['id'],$p['name'],$p['price'],$qty,$line]);$stock->execute([$qty,$p['id']]);}$pdo->commit();unset($_SESSION['cart']);$_SESSION['last_order']=$number;go('order-success.php');}catch(Throwable $e){if(db()->inTransaction())db()->rollBack();$error=$e instanceof RuntimeException?$e->getMessage():'تعذر تسجيل الطلب. حاول مرة أخرى.';}}}?><!doctype html><html lang="ar" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>إتمام الطلب</title><link rel="stylesheet" href="assets/css/store.css"></head><body><?php include __DIR__.'/includes/nav.php';?><main class="inner"><h1>إتمام الطلب</h1><?php if($error):?><p class="notice"><?=h($error)?></p><?php endif?><form method="post" class="checkout-form"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><label>الاسم الكامل<input required name="name" value="<?=h($_POST['name']??'')?>"></label><label>رقم الهاتف<input required name="phone" value="<?=h($_POST['phone']??'')?>" inputmode="tel"></label><label>المدينة<input required name="city" value="<?=h($_POST['city']??'')?>"></label><label>العنوان بالتفصيل<textarea required name="address"><?=h($_POST['address']??'')?></textarea></label><label>ملاحظات إضافية<textarea name="notes"><?=h($_POST['notes']??'')?></textarea></label><h2>الإجمالي: <?=money($total)?></h2><p>طريقة الدفع: الدفع عند الاستلام (تأكيد الطلب هاتفياً).</p><button class="gold">تأكيد الطلب</button></form></main><?php include __DIR__.'/includes/footer.php';?></body></html>